const upsertLocation = `-- name: UpsertLocation :one
INSERT INTO disaster_locations (id, name, latitude, longitude, created_at, updated_at, created_by)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    updated_at = EXCLUDED.updated_at
WHERE EXCLUDED.updated_at > disaster_locations.updated_at
RETURNING id, name, latitude, longitude, created_at, updated_at, created_by
`

type UpsertLocationParams struct {
	ID        uuid.UUID          `json:"id"`
	Name      string             `json:"name"`
	Latitude  float64            `json:"latitude"`
	Longitude float64            `json:"longitude"`
	CreatedAt pgtype.Timestamptz `json:"createdAt"`
	UpdatedAt pgtype.Timestamptz `json:"updatedAt"`
	CreatedBy string             `json:"createdBy"`
}

// Atomic LWW upsert: applies iff new, or existing row is strictly older.
// Returns 0 rows (pgx.ErrNoRows) when blocked — the service falls back to
// GetLocation to classify ignored-stale vs. conflict (equal timestamps).
func (q *Queries) UpsertLocation(ctx context.Context, arg UpsertLocationParams) (DisasterLocation, error) {
	row := q.db.QueryRow(ctx, upsertLocation,
		arg.ID,
		arg.Name,
		arg.Latitude,
		arg.Longitude,
		arg.CreatedAt,
		arg.UpdatedAt,
		arg.CreatedBy,
	)
	var i DisasterLocation
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Latitude,
		&i.Longitude,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CreatedBy,
	)
	return i, err
}

