const upsertPhoto = `-- name: UpsertPhoto :one
INSERT INTO photos (id, site_assessment_id, s3_key, latitude, longitude, condition, created_at, updated_at, created_by)
SELECT
    $1::uuid,
    $2::uuid,
    $3::text,
    $4::float8,
    $5::float8,
    $6::text,
    $7::timestamptz,
    $8::timestamptz,
    $9::text
WHERE EXISTS (SELECT 1 FROM photos WHERE id = $1)
   OR (SELECT count(*) FROM photos WHERE site_assessment_id = $2) < 10
ON CONFLICT (id) DO UPDATE SET
    s3_key = EXCLUDED.s3_key,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    condition = EXCLUDED.condition,
    updated_at = EXCLUDED.updated_at
WHERE EXCLUDED.updated_at > photos.updated_at
RETURNING id, site_assessment_id, s3_key, latitude, longitude, condition, created_at, updated_at, created_by
`

type UpsertPhotoParams struct {
	ID               uuid.UUID          `json:"id"`
	SiteAssessmentID uuid.UUID          `json:"siteAssessmentId"`
	S3Key            string             `json:"s3Key"`
	Latitude         float64            `json:"latitude"`
	Longitude        float64            `json:"longitude"`
	Condition        string             `json:"condition"`
	CreatedAt        pgtype.Timestamptz `json:"createdAt"`
	UpdatedAt        pgtype.Timestamptz `json:"updatedAt"`
	CreatedBy        string             `json:"createdBy"`
}

// Atomic LWW upsert *and* the <=10-photos-per-site rule in one round trip:
// the source SELECT only yields a row when the photo already exists (update
// path, uncapped) or the site is still under the cap (insert path) — so a
// new photo past the cap contributes no row, the INSERT is a no-op, and
// ON CONFLICT never fires. That makes the cap check and the id-conflict
// check race-free without an explicit transaction or row lock: the whole
// decision happens inside one statement.
func (q *Queries) UpsertPhoto(ctx context.Context, arg UpsertPhotoParams) (Photo, error) {
	row := q.db.QueryRow(ctx, upsertPhoto,
		arg.ID,
		arg.SiteAssessmentID,
		arg.S3Key,
		arg.Latitude,
		arg.Longitude,
		arg.Condition,
		arg.CreatedAt,
		arg.UpdatedAt,
		arg.CreatedBy,
	)
	var i Photo
	err := row.Scan(
		&i.ID,
		&i.SiteAssessmentID,
		&i.S3Key,
		&i.Latitude,
		&i.Longitude,
		&i.Condition,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CreatedBy,
	)
	return i, err
}

